function coinMoves(root: TreeNode | null): number {
  let moves = 0;
  const excess = (node: TreeNode | null): number => {
    if (!node) return 0;
    const l = excess(node.left), r = excess(node.right);
    moves += Math.abs(l) + Math.abs(r);
    return node.val - 1 + l + r;
  };
  excess(root);
  return moves;
}

