function coinMoves(root: TreeNode | null): number {
  if (!root) return 0;
  const order: TreeNode[] = [root];
  for (let i = 0; i < order.length; i++) {
    const node = order[i];
    if (node.left) order.push(node.left);
    if (node.right) order.push(node.right);
  }
  const excess = new Map<TreeNode, number>();
  let moves = 0;
  for (let i = order.length - 1; i >= 0; i--) {
    const node = order[i];
    const l = node.left ? excess.get(node.left)! : 0;
    const r = node.right ? excess.get(node.right)! : 0;
    moves += Math.abs(l) + Math.abs(r);
    excess.set(node, node.val - 1 + l + r);
  }
  return moves;
}

